function validate([nums]) {
  if (nums.length < 2 || nums.length > 14) return 'nums needs 2 to 14 values.';
  const seen = new Array(nums.length).fill(false);
  for (const value of nums) {
    if (value < 0 || value >= nums.length || seen[value]) return 'nums must contain each of 0 to n - 1 exactly once.';
    seen[value] = true;
  }
  return null;
}

