function findPermutation(nums) {
  const n = nums.length;
  const full = (1 << n) - 1;
  const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(Infinity));
  for (let last = 0; last < n; last++) {
    dp[full][last] = Math.abs(last - nums[0]);
  }

  for (let mask = full - 1; mask > 0; mask--) {
    if ((mask & 1) === 0) {
      continue;
    }
    for (let last = 0; last < n; last++) {
      if ((mask & (1 << last)) === 0) {
        continue;
      }
      for (let next = 1; next < n; next++) {
        const bit = 1 << next;
        if ((mask & bit) === 0) {
          const cost = Math.abs(last - nums[next]) + dp[mask | bit][next];
          dp[mask][last] = Math.min(dp[mask][last], cost);
        }
      }
    }
  }

  const perm = [0];
  let used = 1;
  while (perm.length < n) {
    const last = perm[perm.length - 1];
    for (let next = 1; next < n; next++) {
      const bit = 1 << next;
      if ((used & bit) === 0 && Math.abs(last - nums[next]) + dp[used | bit][next] === dp[used][last]) {
        perm.push(next);
        used |= bit;
        break;
      }
    }
  }
  return perm;
}

