function findPermutation(nums) {
  // Try every permutation in lexicographic order and keep the first one with the smallest score.
  const n = nums.length;
  let best = null;
  let bestScore = Infinity;
  const perm = [];
  const taken = new Array(n).fill(false);
  const build = () => {
    if (perm.length === n) {
      let score = 0;
      for (let i = 0; i < n; i++) score += Math.abs(perm[i] - nums[perm[(i + 1) % n]]);
      if (score < bestScore) {
        bestScore = score;
        best = perm.slice();
      }
      return;
    }
    for (let value = 0; value < n; value++) {
      if (taken[value]) continue;
      taken[value] = true;
      perm.push(value);
      build();
      perm.pop();
      taken[value] = false;
    }
  };
  build();
  return best;
}

