function generate(rand, size) {
  const n = size === 'large' ? 13 + Math.floor(rand() * 2) : 2 + Math.floor(rand() * 6);
  const nums = Array.from({ length: n }, (_, i) => i);
  const mode = rand();
  // Mostly random shuffles, sometimes the identity or the reversed order.
  if (mode < 0.1) return [nums];
  if (mode < 0.2) return [nums.reverse()];
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
